import os,json,urllib.request,urllib.error,pathlib,sys
ROOT=pathlib.Path(__file__).parent
BASE=os.environ['MCPJAM_API_URL'].rstrip('/')
def call(path,method='GET',body=None,label=None):
 req=urllib.request.Request(BASE+path,data=json.dumps(body).encode() if body is not None else None,method=method,headers={'Authorization':'Bearer '+os.environ['MCPJAM_API_KEY'],'Content-Type':'application/json'})
 try:
  with urllib.request.urlopen(req,timeout=20) as r: status=r.status; data=r.read().decode()
 except urllib.error.HTTPError as e: status=e.code; data=e.read().decode()
 try: result=json.loads(data)
 except ValueError: result={'body':data}
 record={'status':status,'response':result}
 if label:(ROOT/(label+'.json')).write_text(json.dumps(record,indent=2))
 print(path,json.dumps(record))
 return status,result
if __name__=='__main__': call(sys.argv[1],sys.argv[2] if len(sys.argv)>2 else 'GET',json.loads(sys.argv[3]) if len(sys.argv)>3 else None,sys.argv[4] if len(sys.argv)>4 else 'last-response')
